import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
import "core-js/modules/es.set.difference.v2.js";
import "core-js/modules/es.set.intersection.v2.js";
import "core-js/modules/es.set.is-disjoint-from.v2.js";
import "core-js/modules/es.set.is-subset-of.v2.js";
import "core-js/modules/es.set.is-superset-of.v2.js";
import "core-js/modules/es.set.symmetric-difference.v2.js";
import "core-js/modules/es.set.union.v2.js";
import { ref, computed, onMounted, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router'; // 添加 useRouter 导入
import { useStore } from 'vuex';
import { ElMessage, ElMessageBox } from 'element-plus';
import 'element-plus/es/components/message-box/style/css';
import 'element-plus/es/components/message/style/css';
import axios from 'axios';
import { API_CONFIG } from '@/config/config';
import defaultAvatar from '@/assets/default-avatar.png';
import { extractAndNormalizeId } from '@/store/modules/chat'; // 导入辅助函数
import _ from 'lodash';
export default {
  name: 'GroupInfo',
  props: {
    visible: {
      type: Boolean,
      default: false
    },
    groupInfo: {
      type: Object,
      default: () => ({})
    }
  },
  emits: ['update:visible', 'group-updated', 'group-exited'],
  setup(props, {
    emit
  }) {
    const store = useStore();
    const currentUserId = computed(() => store.state.user.id);
    const currentUser = computed(() => store.state.user);
    const router = useRouter(); // 正确初始化 router
    const route = useRoute();
    const groupMembers = ref([]);
    const isMuted = ref(false);
    const showEditName = ref(false);
    const editGroupName = ref('');
    const showAddMember = ref(false);
    const searchKeyword = ref('');
    const selectedUserIds = ref(new Set());
    const allUsers = ref([]);
    const hoverMemberId = ref(null);
    const isGroupOwner = computed(() => {
      return props.groupInfo.creator_id === currentUserId.value;
    });
    // 添加获取成员ID的方法
    const getMemberId = member => {
      if (!member) return null;
      return typeof member === 'number' ? member : member.id;
    };
    // 计算属性：有效的群组成员
    const validGroupMembers = computed(() => {
      return (groupMembers.value || []).filter(member => member && (typeof member === 'object' || typeof member === 'number') && (member.id !== undefined || typeof member === 'number'));
    });
    console.log("有效的群组成员:", validGroupMembers.value);
    const groupAvatarUrls = computed(() => {
      console.log("计算群头像，当前群信息:", props.groupInfo);
      if (!props.groupInfo) return [defaultAvatar];
      const avatarMembers = props.groupInfo.avatar_members || [];

      // 优先使用 avatar_members
      if (avatarMembers.length > 0) {
        return avatarMembers.slice(0, 9).map(url => getFullUrl(url)).filter(Boolean);
      }

      // 如果没有 avatar_members，使用群成员的头像
      if (groupMembers.value && groupMembers.value.length > 0) {
        return groupMembers.value.slice(0, 9).map(member => {
          if (typeof member === 'object' && member.photo) {
            return getFullUrl(member.photo);
          }
          return defaultAvatar;
        });
      }

      // 如果都没有，使用默认头像
      return [defaultAvatar];
    });

    // 过滤用户列表（支持用户名、电话、邮箱搜索）
    const filteredUsers = computed(() => {
      if (!searchKeyword.value) return allUsers.value;
      const keyword = searchKeyword.value.toLowerCase();
      return allUsers.value.filter(user => user.username && user.username.toLowerCase().includes(keyword) || user.phone && user.phone.includes(keyword) || user.email && user.email.toLowerCase().includes(keyword) || user.id && user.id.toString().includes(keyword));
    });
    // 检查用户是否已在群中
    const isUserInGroup = userId => {
      return validGroupMembers.value.some(member => {
        const memberId = typeof member === 'object' ? member.id : member;
        return memberId === userId;
      });
    };
    const getFullUrl = path => {
      if (!path) return defaultAvatar;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };
    const getAvatarPosition = index => {
      const positions = [{
        top: '0%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '0%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '33%',
        left: '33%',
        width: '33%',
        height: '33%'
      }];
      return positions[index] || positions[0];
    };
    const getMemberAvatar = member => {
      if (!member) return defaultAvatar;
      if (typeof member === 'number') {
        return defaultAvatar;
      }
      if (!member.photo) {
        return defaultAvatar;
      }
      return getFullUrl(member.photo);
    };
    const getMemberRole = member => {
      if (!member) return '成员';
      const memberId = typeof member === 'number' ? member : member.id;
      if (memberId === props.groupInfo.creator_id) return '群主';
      return '成员';
    };
    const getMemberName = member => {
      if (!member) return '未知用户';
      if (typeof member === 'number') return `用户 ${member}`;
      return member.username || `用户 ${member.id}`;
    };
    const getMemberKey = member => {
      if (typeof member === 'number') return member;
      if (member && member.id) return member.id;
      return Math.random();
    };
    const canRemoveMember = member => {
      if (!member) return false;
      console.log("检查是否可以移除成员:", member, currentUserId.value, props.groupInfo.creator_id);
      const memberId = typeof member === 'number' ? member : member.id;
      if (!memberId) return false;
      if (memberId === currentUserId.value) return false;
      if (memberId === props.groupInfo.creator_id) return false;
      return true;
    };
    const close = () => {
      emit('update:visible', false);
    };
    const loadGroupMembers = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/members`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data) {
          const membersData = response.data.group_members || [];
          console.log("加载到的群成员数据:", membersData);
          if (Array.isArray(membersData) && membersData.length > 0) {
            if (typeof membersData[0] === 'number') {
              // 如果是ID数组，转换为成员对象
              groupMembers.value = membersData.map(id => ({
                id: id,
                username: `用户 ${id}`,
                photo: null
              }));
            } else {
              // 已经是完整的成员对象
              groupMembers.value = membersData.filter(member => member && typeof member === 'object' && member.id !== undefined);
            }
          } else {
            groupMembers.value = [];
          }
        }
      } catch (error) {
        console.error('加载群成员失败:', error);
        ElMessage.error('加载群成员失败');
      }
    };

    // 检查当前群组是否有效
    const checkGroupValidity = async () => {
      const groupId = route.params.id;
      if (!groupId) return;

      // 检查是否是群聊ID
      const isGroup = typeof groupId === 'string' && groupId.startsWith('group_');
      if (!isGroup) return;

      // 检查用户是否还在这个群组中
      const joinedGroups = store.getters['chat/getJoinedGroups'];
      const groupExists = joinedGroups.some(group => extractAndNormalizeId(group) === extractAndNormalizeId({
        id: groupId,
        isGroup: true
      }));
      if (!groupExists) {
        // 群组不存在或用户已退出，重定向到聊天列表
        ElMessage.warning('您已退出该群组或群组不存在');
        router.push('/chats');
      }
    };

    // 加载所有用户（从/user/get-users接口）
    const loadAllUsers = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/user/get-users`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data && Array.isArray(response.data)) {
          // 过滤掉已经是群成员的用户
          const memberIds = new Set(validGroupMembers.value.map(m => typeof m === 'number' ? m : m.id));
          allUsers.value = response.data.filter(user => user && user.id && !memberIds.has(user.id));
        } else {
          allUsers.value = [];
        }
      } catch (error) {
        console.error('加载用户列表失败:', error);
        ElMessage.error('加载用户列表失败');
        allUsers.value = [];
      }
    };
    // 搜索输入防抖处理
    const handleSearchInput = _.debounce(() => {
      // 搜索逻辑已经在filteredUsers计算属性中实现
    }, 300);
    const showEditNameDialog = () => {
      editGroupName.value = props.groupInfo.group_name || '';
      showEditName.value = true;
    };
    const cancelEditName = () => {
      showEditName.value = false;
    };
    const confirmEditName = async () => {
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/update-name`, {
          group_id: props.groupInfo.group_id,
          name: editGroupName.value
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('群名称修改成功');
          showEditName.value = false;

          // 更新Vuex store中的群组信息
          store.commit('chat/UPDATE_JOINED_GROUP', {
            group_id: props.groupInfo.group_id,
            name: editGroupName.value,
            ...props.groupInfo
          });
          emit('group-updated');
          emit('update:visible', false);
        } else {
          ElMessage.error(response.data.message || '修改失败');
          showEditName.value = false;
        }
      } catch (error) {
        console.error('修改群名称失败:', error);
        ElMessage.error('修改群名称失败');
        showEditName.value = false;
      }
    };
    const toggleMute = async () => {
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute?user_id=${currentUserId.value}`, {
          muted: !isMuted.value,
          user_id: currentUserId.value
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          isMuted.value = !isMuted.value;
          ElMessage.success(isMuted.value ? '已开启消息免打扰' : '已关闭消息免打扰');
        }
      } catch (error) {
        console.error('设置消息免打扰失败:', error);
        ElMessage.error('设置失败');
      }
    };
    const removeMember = async member => {
      console.log("=== 开始移除成员 ===");
      console.log("成员对象:", member);
      if (!member) {
        console.error("成员信息无效");
        ElMessage.error('成员信息无效');
        return;
      }
      const memberId = typeof member === 'number' ? member : member.id;
      const memberName = typeof member === 'number' ? `用户 ${member}` : member.username || `用户 ${member.id}`;
      try {
        // 确认对话框
        try {
          await ElMessageBox.confirm(`确定要将 ${memberName} 移出群聊吗？`, '确认移除', {
            type: 'warning',
            confirmButtonText: '确定移除',
            cancelButtonText: '取消'
          });
        } catch (confirmError) {
          // 用户点击了取消
          console.log("用户取消了操作");
          return;
        }
        console.log("用户确认移除，调用API");

        // 调用API移除成员
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/remove-member`, {
          group_id: props.groupInfo.group_id,
          user_id: memberId
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          },
          timeout: 10000
        });
        console.log("API响应:", response.data);
        if (response.data.success) {
          ElMessage.success('成员已移除');

          // 重新加载群成员
          await loadGroupMembers();

          // 重新加载可添加的用户列表
          await loadAllUsers();

          // 通知父组件更新
          emit('group-updated');
        } else {
          console.error("API返回失败:", response.data);
          ElMessage.error(response.data.message || '移除成员失败');
        }
      } catch (error) {
        console.error("移除过程中出错:", error);

        // 详细的错误处理
        if (error.response) {
          console.error("服务器响应错误:", error.response);
          const status = error.response.status;
          if (status === 403) {
            ElMessage.error('没有权限移除成员');
          } else if (status === 404) {
            if (error.response.data?.detail?.includes("群组不存在")) {
              ElMessage.error('群组不存在');
            } else if (error.response.data?.detail?.includes("该用户不在群组中")) {
              ElMessage.error('该用户不在群组中');
            } else {
              ElMessage.error('群组或成员不存在');
            }
          } else if (status === 400) {
            if (error.response.data?.detail?.includes("不能移除自己")) {
              ElMessage.error('不能移除自己');
            } else if (error.response.data?.detail?.includes("不能移除群主")) {
              ElMessage.error('不能移除群主');
            } else {
              ElMessage.error(error.response.data?.detail || '请求参数错误');
            }
          } else {
            ElMessage.error(error.response.data?.message || '移除成员失败');
          }
        } else if (error.request) {
          console.error("网络请求错误:", error.request);
          ElMessage.error('网络错误，请检查连接');
        } else {
          console.error("其他错误:", error);
          ElMessage.error('移除成员失败');
        }
      }
    };

    // 解散群聊
    const dismissGroup = async () => {
      try {
        await ElMessageBox.confirm('确定要解散该群聊吗？解散后所有成员将被移除，且无法恢复', '确认解散', {
          type: 'warning',
          confirmButtonText: '确定解散',
          cancelButtonText: '取消'
        });
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/dismiss`, {
          group_id: props.groupInfo.group_id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('群聊已解散');

          // 从已加入群组中移除该群组
          store.commit('chat/REMOVE_JOINED_GROUP', props.groupInfo.group_id);
          close();
          emit('group-exited');

          // 重定向到聊天列表
          router.push('/chats');
        }
      } catch (error) {
        if (error !== 'cancel') {
          console.error('解散群聊失败:', error);

          // 详细的错误处理
          if (error.response) {
            const status = error.response.status;
            if (status === 403) {
              ElMessage.error('没有权限解散群聊');
            } else if (status === 404) {
              ElMessage.error('群组不存在');
            } else if (status === 400) {
              if (error.response.data?.detail?.includes("群组已被解散")) {
                ElMessage.error('群组已被解散');
              } else {
                ElMessage.error(error.response.data?.detail || '请求参数错误');
              }
            } else {
              ElMessage.error(error.response.data?.message || '解散群聊失败');
            }
          } else {
            ElMessage.error('解散群聊失败');
          }
        }
      }
    };

    // 退出群聊
    const exitGroup = async () => {
      try {
        await ElMessageBox.confirm('确定要退出该群聊吗？退出后将不再接收该群消息', '确认退出', {
          type: 'warning'
        });
        await store.dispatch('chat/exitGroup', props.groupInfo.group_id);

        // 清除当前选中的聊天ID（关键修复）

        ElMessage.success('已退出群聊');
        close();
        emit('group-exited');

        // 重定向到聊天列表
        router.push('/chats');
      } catch (error) {
        if (error !== 'cancel') {
          console.error('退出群聊失败:', error);
        }
      }
    };
    const showAddMemberDialog = async () => {
      await loadAllUsers();
      showAddMember.value = true;
      selectedUserIds.value.clear();
      searchKeyword.value = '';
    };
    const closeAddMemberDialog = () => {
      showAddMember.value = false;
    };
    const selectUser = user => {
      if (selectedUserIds.value.has(user.id)) {
        selectedUserIds.value.delete(user.id);
      } else {
        selectedUserIds.value.add(user.id);
      }
    };
    const isUserSelected = userId => {
      return selectedUserIds.value.has(userId);
    };
    const confirmAddMembers = async () => {
      if (selectedUserIds.value.size === 0) {
        ElMessage.warning('请选择要添加的成员');
        return;
      }
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/add-members`, {
          group_id: props.groupInfo.group_id,
          user_ids: Array.from(selectedUserIds.value)
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('成员添加成功');
          await loadGroupMembers();
          await loadAllUsers();
          closeAddMemberDialog();
          emit('group-updated');
        }
      } catch (error) {
        console.error('添加成员失败:', error);
        ElMessage.error('添加成员失败');
      }
    };
    watch(() => props.visible, async newVisible => {
      if (newVisible && props.groupInfo.group_id) {
        await loadGroupMembers();
        try {
          const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute-status?user_id=${currentUserId.value}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (response.data.success) {
            isMuted.value = response.data.muted;
          }
        } catch (error) {
          console.error('获取免打扰状态失败:', error);
        }
      }
    });

    // 监听路由变化
    watch(() => route.params.id, newId => {
      if (newId) {
        checkGroupValidity();
      }
    });
    onMounted(async () => {
      if (props.visible && props.groupInfo.group_id) {
        await loadGroupMembers();
        checkGroupValidity();
        try {
          const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute-status?user_id=${currentUserId.value}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (response.data.success) {
            isMuted.value = response.data.muted;
          }
        } catch (error) {
          console.error('获取免打扰状态失败:', error);
        }
      }
    });
    return {
      currentUserId,
      groupMembers,
      validGroupMembers,
      currentUser,
      isMuted,
      showEditName,
      editGroupName,
      showAddMember,
      searchKeyword,
      filteredUsers,
      isGroupOwner,
      dismissGroup,
      groupAvatarUrls,
      getFullUrl,
      hoverMemberId,
      handleSearchInput,
      isUserInGroup,
      getAvatarPosition,
      getMemberAvatar,
      getMemberRole,
      getMemberName,
      getMemberId,
      getMemberKey,
      canRemoveMember,
      close,
      showEditNameDialog,
      cancelEditName,
      confirmEditName,
      toggleMute,
      removeMember,
      exitGroup,
      showAddMemberDialog,
      closeAddMemberDialog,
      selectUser,
      isUserSelected,
      confirmAddMembers
    };
  }
};
